// Generates lsp-core's shipped copy of the ZenWave SDK plugin catalogue (ShippedPluginCatalogue.kt).
//
//   node scripts/generate-plugin-catalogue.mjs --from <sdk-plugin-catalogue.json> [--out <file.kt>]
//
// The input is the catalogue as the VS Code extension's scripts/generate-sdk-catalogue.mjs writes it from
// `jbang snapshots@zenwave360/zenwave-sdk -h json`, so the build the copy comes from is named in its
// "source" and "version" fields, and the generated file repeats them. To refresh the copy from the SDK:
// run that extension script (or the same SDK command) to get the JSON, then run this script on it.
//
// The JSON is minified and written as chunks: a JVM class constant is limited to 65535 bytes.
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseArgs } from 'node:util';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const { values } = parseArgs({ options: { from: { type: 'string' }, out: { type: 'string' } } });
if (!values.from) throw new Error('--from <sdk-plugin-catalogue.json> is required');
const out = resolve(
  values.out ?? resolve(root, 'lsp-core/src/commonMain/kotlin/io/zenwave360/lsp/core/catalogue/ShippedPluginCatalogue.kt'),
);

const catalogue = JSON.parse(readFileSync(values.from, 'utf8'));
if (!Array.isArray(catalogue.plugins) || typeof catalogue.version !== 'string' || typeof catalogue.source !== 'string') {
  throw new Error('The input is not an SDK plugin catalogue: source, version and plugins are required');
}
const json = JSON.stringify(catalogue);
const sha256 = createHash('sha256').update(json).digest('hex');

// A Kotlin string literal for ASCII text: backslash, quote and dollar escaped, anything else as \uXXXX.
const escape = (text) => {
  let result = '';
  for (let index = 0; index < text.length; index += 1) {
    const ch = text[index];
    const code = text.charCodeAt(index);
    if (ch === '\\') result += '\\\\';
    else if (ch === '"') result += '\\"';
    else if (ch === '$') result += '\\$';
    else if (code < 0x20 || code > 0x7e) result += '\\u' + code.toString(16).padStart(4, '0');
    else result += ch;
  }
  return result;
};
const chunks = [];
for (let index = 0; index < json.length; index += 8000) {
  const end = Math.min(index + 8000, json.length);
  chunks.push(json.slice(index, end));
}

const lines = [
  'package io.zenwave360.lsp.core.catalogue',
  '',
  'import io.zenwave360.language.docs.PluginCatalogue',
  '',
  '// GENERATED by scripts/generate-plugin-catalogue.mjs. Do not edit: regenerate it from an SDK catalogue.',
  `// Source: ${catalogue.source} (version ${catalogue.version}), ${catalogue.plugins.length} plugins, minified JSON sha256 ${sha256}.`,
  '',
  "/** The server's own copy of the ZenWave SDK plugin catalogue (MP-R16). A client can replace it while the server runs. */",
  'object ShippedPluginCatalogue {',
  '    /** The SDK build the copy was generated from, as its `source` and `version` name it. */',
  `    const val SOURCE = "${escape(catalogue.source)}"`,
  `    const val VERSION = "${escape(catalogue.version)}"`,
  '',
  '    /** The catalogue JSON, as the extension ships it, minified. */',
  '    fun json(): String = CHUNKS.joinToString("")',
  '',
  '    /** Parses the copy; the first caller pays for it. */',
  '    fun catalogue(): PluginCatalogue = PluginCatalogue.parse(json())',
  '',
  '    private val CHUNKS = listOf(',
  ...chunks.map((chunk) => `        "${escape(chunk)}",`),
  '    )',
  '}',
  '',
];
writeFileSync(out, lines.join('\n'));
console.log(`Wrote ${out}: ${catalogue.plugins.length} plugins from ${catalogue.source}, ${json.length} characters in ${chunks.length} chunks`);
